// Temporary Playwright config of the cross-browser matrix (task E2, 2026-09-05).
// Lives in the evidence directory on purpose: apps/web/playwright.config.ts only gained the optional
// firefox/webkit projects; everything else of the matrix runs from here against temporary spec copies
// (apps/web/e2e/*-xb.tmp.spec.ts, generated by make-tmp-specs.mjs and deleted afterwards):
//   - xb-func-<engine>:   marketing.spec.ts + app.spec.ts (unmodified tests + the WebKit header hook)
//   - xb-visual-<engine>: visual.spec.ts compared against the committed Chromium baselines (never updated)
//   - xb-lac-<engine>:    Living AI Core tiers on /app
//   - xb-mobile-*:        device emulation (iPhone 14 → WebKit, Pixel 7 → Chromium)
//
//   cd apps/web
//   XB_OUT=<results dir> XB_TEST_RESULTS=<scratch dir> E2E_BASE_URL=http://localhost:3013 pnpm exec playwright test \
//     --config ../../docs/qa/2026-09-05/followup/browsers/playwright.xbrowser.config.mjs --project=<name> --update-snapshots=none
//
// `@playwright/test` is resolved from apps/web (the same instance the CLI and the specs use).
import { createRequire } from "node:module";
import path from "node:path";

const WEB = "C:/Users/Soheil/Downloads/track.site/apps/web";
const require = createRequire(path.join(WEB, "package.json"));
const { defineConfig, devices } = require("@playwright/test");

const AUTH_FILE = path.join(WEB, "e2e/.auth/owner.json");
const OUT = process.env.XB_OUT ?? path.join(WEB, "test-results-xbrowser");

/** Same capture context as the `visual` project of apps/web/playwright.config.ts. */
const visualUse = { deviceScaleFactor: 1, timezoneId: "Europe/Berlin", contextOptions: { reducedMotion: "reduce" } };
const FUNC = /(marketing|app)-xb\.tmp\.spec\.ts$/;
const VISUAL = /visual-xb\.tmp\.spec\.ts$/;
const LAC = /xbrowser-lac\.tmp\.spec\.ts$/;
const MOBILE = /xbrowser-mobile\.tmp\.spec\.ts$/;

export default defineConfig({
  testDir: path.join(WEB, "e2e"),
  timeout: 60_000,
  retries: 0,
  workers: 1,
  reporter: [["list"], ["json", { outputFile: path.join(OUT, "results.json") }]],
  // traces and raw PNG diffs stay outside the evidence directory (XB_TEST_RESULTS → scratch dir); the summary references converted WebPs
  outputDir: process.env.XB_TEST_RESULTS ?? path.join(OUT, "test-results"),
  use: {
    baseURL: process.env.E2E_BASE_URL ?? "http://localhost:3013",
    trace: "retain-on-failure",
    locale: "en-US",
  },
  // Every engine is compared against the committed Chromium baselines (…-visual-win32.png): the matrix reports
  // mismatches per engine; it never writes baselines (run with --update-snapshots=none).
  snapshotPathTemplate: "{testDir}/__screenshots__/{arg}-visual-{platform}{ext}",
  projects: [
    { name: "xb-func-webkit", testMatch: FUNC, use: { ...devices["Desktop Safari"], storageState: AUTH_FILE } },
    { name: "xb-func-chromium", testMatch: FUNC, use: { ...devices["Desktop Chrome"], storageState: AUTH_FILE } },
    { name: "xb-visual-chromium", testMatch: VISUAL, use: { ...devices["Desktop Chrome"], storageState: AUTH_FILE, ...visualUse } },
    { name: "xb-visual-webkit", testMatch: VISUAL, use: { ...devices["Desktop Safari"], storageState: AUTH_FILE, ...visualUse } },
    { name: "xb-visual-firefox", testMatch: VISUAL, use: { ...devices["Desktop Firefox"], storageState: AUTH_FILE, ...visualUse } },
    { name: "xb-lac-chromium", testMatch: LAC, use: { ...devices["Desktop Chrome"], storageState: AUTH_FILE } },
    { name: "xb-lac-webkit", testMatch: LAC, use: { ...devices["Desktop Safari"], storageState: AUTH_FILE } },
    { name: "xb-lac-firefox", testMatch: LAC, use: { ...devices["Desktop Firefox"], storageState: AUTH_FILE } },
    { name: "xb-mobile-webkit-iphone14", testMatch: MOBILE, use: { ...devices["iPhone 14"], storageState: AUTH_FILE } },
    { name: "xb-mobile-chromium-pixel7", testMatch: MOBILE, use: { ...devices["Pixel 7"], storageState: AUTH_FILE } },
  ],
});
